/// Parsed global flags + the `link add`/`link set` contract-target flags (#3786) + leftover positional
/// args.
struct Args {
    json: bool,
    /// `--kind api|data|events` — `link set` only: the contract kind, which RE-KEYS the link. `add`
    /// takes its kind positionally, so this flag never applies there.
    kind: Option<String>,
    /// `--target-type project|service|mcp` (default project) — the endpoint kind a contract points at.
    target_type: Option<String>,
    /// `--name` — display name of an external endpoint.
    name: Option<String>,
    /// `--url` — the endpoint URL.
    url: Option<String>,
    /// `--app-type` — the endpoint's application-architecture discriminator (api | serverless | …).
    app_type: Option<String>,
    /// `--pitch` — `new` only: the one-line brief the project starts from.
    pitch: Option<String>,
    /// `--blueprint` — `new` only: the blueprint id that seeds the plan.
    blueprint: Option<String>,
    /// `--network` — `new` only: the network to file the project into. Absent, an ARCHITECT's session
    /// supplies its own (see [`resolve_network`]); any other caller creates the project unfiled.
    network: Option<String>,
    /// `--direction source|runtime` — `integrations` only: which half of the work list to return.
    direction: Option<String>,
    positional: Vec<String>,
}

/// Which NETWORK a new project belongs to: the `--network` flag, else the one the CREATING SESSION
/// belongs to, else none.
///
/// WHY INFER AT ALL. An architect is per network, and the project it creates is part of that network's
/// domain — but `bsc project new` took no network, so every project an architect created started
/// UNFILED. Glance scopes each tab by network, so an unfiled project is drawn in no tab, and neither is
/// its director: indistinguishable, from the user's side, from the create having failed. That was
/// reported as "the finance architect failed to create a director".
///
/// A FLAG WOULD NOT HAVE FIXED IT. The charter would have to remember to pass it on every create, and
/// the one it forgets is silently unfiled again. The session already knows the answer, so it answers.
///
/// ONLY A NETWORK ARCHITECT'S PANE COUNTS. `BSC_AUDIT_PANE` is `<key>:<tail>` for every session in the
/// app, so a worker at `studio-code:auth` would otherwise file its project into a "network" named
/// `studio-code`. The pane must be exactly `<key>:architect` AND the key must be a `network-` id — the
/// grammar `bsc network` mints and `bsc_session::network_architect_slug` validates.
///
/// Pure, and takes the environment as an argument for the same reason `resolve_origin` does: the rule
/// is testable without a process environment.
fn resolve_network(flag: Option<String>, audit_pane: Option<String>) -> Option<String> {
    let clean = |s: Option<String>| s.map(|v| v.trim().to_string()).filter(|v| !v.is_empty() && v != "?");
    if let Some(explicit) = clean(flag) {
        return Some(explicit);
    }
    let pane = clean(audit_pane)?;
    let (key, tail) = pane.split_once(':')?;
    (tail == "architect" && key.starts_with("network-") && key.len() > "network-".len())
        .then(|| key.to_string())
}

/// A flag value that is actually a value: trimmed, with an empty one dropped to `None`. `link add`
/// uses it so an empty descriptor is stored as ABSENT rather than as `""` — the same normalization
/// `update_contract` applies when a `set` clears one, so the two verbs cannot disagree about what an
/// empty flag means.
fn nonempty(v: &Option<String>) -> Option<String> {
    v.as_deref().map(str::trim).filter(|s| !s.is_empty()).map(str::to_string)
}

fn parse_args(raw: Vec<String>) -> Result<Args, String> {
    let mut a = Args { json: false, kind: None, target_type: None, name: None, url: None, app_type: None, pitch: None, blueprint: None, network: None, direction: None, positional: Vec::new() };
    // A value flag consumes the NEXT token, so iterate with an index rather than a plain for-each.
    let mut it = raw.into_iter();
    while let Some(arg) = it.next() {
        // The value flags (#3786) take `<flag> <value>`; missing the value is an error.
        let mut take = |flag: &str| it.next().ok_or_else(|| format!("{flag} needs a value"));
        match arg.as_str() {
            "--json" => a.json = true,
            // `-h`/`--help` route to the help command (anywhere on the line).
            "-h" | "--help" => a.positional.insert(0, "help".into()),
            "--kind" => a.kind = Some(take("--kind")?),
            "--target-type" => a.target_type = Some(take("--target-type")?),
            "--name" => a.name = Some(take("--name")?),
            "--url" => a.url = Some(take("--url")?),
            "--app-type" => a.app_type = Some(take("--app-type")?),
            "--pitch" => a.pitch = Some(take("--pitch")?),
            "--blueprint" => a.blueprint = Some(take("--blueprint")?),
            "--network" => a.network = Some(take("--network")?),
            "--direction" => a.direction = Some(take("--direction")?),
            other if other.starts_with("--") => return Err(format!("unknown flag '{other}'")),
            _ => a.positional.push(arg),
        }
    }
    Ok(a)
}

/// The `project` subcommand entrypoint: `args` is everything after `bsc project`; `prog` is the
/// display name for help/errors (`"bsc project"` from the umbrella, `"bsc-project"` from the legacy
/// shim). Handles help (no command / `help` / `help <cmd>` / `<cmd> help`) before any store read.
pub fn run(args: Vec<String>, prog: &str) -> Result<(), String> {
    let args = parse_args(args)?;
    let cmd = args.positional.first().cloned().unwrap_or_default();

    if bsc_cli_util::handle_help(prog, TAGLINE, COMMANDS, &args.positional) {
        return Ok(());
    }

    match cmd.as_str() {
        "integrations" => cmd_integrations(&args),
        "new" => cmd_new(&args, prog),
        "list" => cmd_list(&args),
        "progress" => cmd_progress(&args),
        "triaged" => cmd_triaged(&args, prog),
        "architect" => cmd_architect(&args, prog),
        "network" => cmd_network(&args, prog),
        "published" => cmd_published(&args, prog),
        "link" => cmd_link(&args, prog),
        "github-state" => cmd_github_state(&args, prog),
        "db" => cmd_db(&args, prog),
        other => Err(bsc_cli_util::unknown_command(prog, TAGLINE, COMMANDS, other)),
    }
}

/// `new "<name>"` — create a project from a name (#architect-starts-a-new-project).
///
/// The whole verb is: derive the frozen key, refuse a collision, write a drafted row. It deliberately
/// does NOT scaffold the hub directory — `setup_workspaces` owns that and runs when the project is
/// actually opened, so creating one from a conversation leaves no empty folder behind if the idea is
/// dropped. The durable row is what makes it a project; the folder is what makes it a workspace.
fn cmd_new(args: &Args, prog: &str) -> Result<(), String> {
    let name = args
        .positional
        .get(1)
        .map(|s| s.trim())
        .filter(|s| !s.is_empty())
        .ok_or_else(|| format!("usage: {prog} new \"<name>\" [--pitch \"<text>\"] [--blueprint <id>] [--network <id>]"))?;

    let key = crate::project_slug(name);
    let conn = store::open()?;

    // TWO collision checks, because there are two places a project can already exist and either one
    // makes this name taken. The store row is the durable identity; the hub is what a PRE-store
    // project (or one whose row was removed) left on disk. Adopting either silently would hand the
    // caller someone else's plan under a name it believes it just created.
    if let Some(existing) = store::get(&conn, &key) {
        return Err(format!(
            "'{name}' slugs to '{key}', which already exists: \"{}\" ({}).\n\
             Pick a different name — a project's key is frozen at creation, so two projects cannot \
             share one.",
            existing.title, existing.state
        ));
    }
    if crate::project_dir(&key).is_some_and(|d| d.exists()) {
        return Err(format!(
            "'{name}' slugs to '{key}', and a project hub already exists at that path.\n\
             Pick a different name, or open the existing project."
        ));
    }

    let now = bsc_util::now_ms();
    let row = ProjectRow {
        key: key.clone(),
        title: name.to_string(),
        pitch: args.pitch.clone().unwrap_or_default(),
        blueprint: args.blueprint.clone(),
        category: None,
        // `drafted` is the honest state: nothing is planned, published or on disk yet.
        state: "drafted".into(),
        triaged_at: None,
        architect: None,
        // The creating session's own network, so an architect's project lands in its domain rather
        // than nowhere. See `resolve_network`.
        network: resolve_network(args.network.clone(), std::env::var("BSC_AUDIT_PANE").ok()),
        created_at: now,
        updated_at: now,
    };
    store::upsert(&conn, &row)?;
    let stored = store::get(&conn, &key).ok_or("project new: row vanished after upsert")?;

    if args.json {
        bsc_sqlite_util::print_json(&stored, false);
    } else {
        println!("{key}");
    }
    Ok(())
}

/// `list` — every local project: key + published + absolute path. Human TSV (one row each) or, with
/// `--json`, an array of `{ key, published, path }`.
/// `integrations` — every project's Discovery-declared integrations, tagged by project (#4055).
///
/// The Integrator studio (#4023) is a global singleton: one session, one workspace, no project
/// context. Its work list is per-project data, so something has to bridge the two, and this is that
/// bridge — item 4055 weighed enumerating hubs, a roll-up read, and per-project Integrator sessions,
/// and chose the roll-up. It lives on `bsc project` because the roster of projects is this noun's
/// job and `bsc plan` binds to a single store by design.
///
/// The same read serves Glance's project→integration edge, so the graph and the Integrator cannot
/// disagree about which projects want what.
fn cmd_integrations(args: &Args) -> Result<(), String> {
    if let Some(d) = args.direction.as_deref() {
        if !plandb::DIRECTIONS.contains(&d) {
            // Rejected loudly rather than filtered to nothing: a typo would otherwise return an empty
            // work list, which reads exactly like "nobody declared anything".
            return Err(format!(
                "unknown --direction '{d}' — expected one of {:?}",
                plandb::DIRECTIONS
            ));
        }
    }
    let base = bsc_util::bsc_base_dir().ok_or("cannot resolve ~/.base-studio-code")?;
    let scan = plandb::scan_declared_integrations(&base.join("plans"), args.direction.as_deref());

    if args.json {
        println!(
            "{}",
            serde_json::to_string(&scan).unwrap_or_else(|_| "{}".into())
        );
        return Ok(());
    }
    if scan.integrations.is_empty() {
        println!("(no integrations declared in any project)");
    } else {
        for d in &scan.integrations {
            let i = &d.integration;
            let name = if i.name.is_empty() { i.id.clone() } else { format!("{} ({})", i.name, i.id) };
            println!(
                "{}\t{}\t{}\t{}",
                d.project,
                i.direction,
                name,
                i.docs.as_deref().or(i.base_url.as_deref()).unwrap_or("")
            );
        }
    }
    // Never silent about what could not be read — an incomplete list that looks complete is the
    // failure this whole scan is shaped to avoid.
    if !scan.unreadable.is_empty() {
        println!("({} plan store(s) unreadable: {})", scan.unreadable.len(), scan.unreadable.join(", "));
    }
    Ok(())
}

fn cmd_list(args: &Args) -> Result<(), String> {
    let projects = list_projects();
    if args.json {
        let arr: Vec<serde_json::Value> = projects
            .iter()
            .map(|p| serde_json::json!({ "key": p.key, "published": p.published, "path": p.path.to_string_lossy() }))
            .collect();
        println!("{}", serde_json::to_string(&arr).unwrap_or_else(|_| "[]".into()));
    } else if projects.is_empty() {
        println!("(no local projects)");
    } else {
        for p in &projects {
            println!(
                "{}\t{}\t{}",
                p.key,
                if p.published { "published" } else { "unpublished" },
                p.path.to_string_lossy()
            );
        }
    }
    Ok(())
}

/// One project's issue completion, as counts (#4052). Counts, never a ratio — a caller can render
/// "3/7" as readily as a bar, and neither has to reconstruct the other.
#[derive(Debug, PartialEq, Eq)]
pub struct ProjectProgress {
    pub key: String,
    pub done: usize,
    pub total: usize,
}

/// Count one plan.db's issues as `(done, total)`. `None` when the file has no readable `issues`
/// table — a hub scaffolded but never planned, which is ABSENT rather than empty (see `cmd_progress`).
///
/// Read-only + `busy_timeout`'d through the shared opener, because a live fleet is writing these very
/// rows while this reads them; a plain `open` would surface a transient lock as a hard error and
/// blank a project that is merely busy.
fn count_issues(db: &std::path::Path) -> Option<(usize, usize)> {
    if !db.is_file() {
        return None;
    }
    let conn = bsc_sqlite_util::open_db(db).ok()?;
    let mut stmt = conn.prepare("SELECT status, COUNT(*) FROM issues GROUP BY status").ok()?;
    let rows = stmt.query_map([], |r| Ok((r.get::<_, String>(0)?, r.get::<_, i64>(1)?))).ok()?;
    let (mut done, mut total) = (0usize, 0usize);
    for row in rows.flatten() {
        let (status, n) = (row.0, row.1.max(0) as usize);
        total += n;
        // An unknown status counts toward the DENOMINATOR only — `is_done_status` is deliberately
        // conservative, so a typo can never inflate a completion count.
        if plandb::is_done_status(&status) {
            done += n;
        }
    }
    // #4118: a project whose `issues` table is EMPTY still owns work — the fleet's streams carry it as
    // GitHub refs, which is the ONLY record for a fleet assembled outside a full planner run (measured:
    // 40 streams, 56 refs, 0 issue rows). Reporting 0/0 there is not "no progress", it is "no data", and
    // the two are indistinguishable to every caller: a total of 0 suppresses the bar entirely, so the
    // project reads as owning nothing. Fall back to the refs so the DENOMINATOR is real.
    //
    // `done` stays 0 on this path on purpose. The refs are GitHub issue numbers and this is a local
    // SQLite read with no network — claiming completion it cannot verify would be the one error worse
    // than showing none. The frontend overlays real closed-ness (#4102/#4103) where it has a token.
    if total == 0 {
        return Some((0, count_stream_refs(&conn)));
    }
    Some((done, total))
}

/// How many distinct issue refs this project's fleet streams OWN (#4118).
///
/// `fleet_streams.data` is a JSON blob per stream carrying `issues: ["#3898", …]`. De-duplicated across
/// streams: two streams naming the same ref are one piece of work, and double-counting would inflate
/// every denominator on the board.
fn count_stream_refs(conn: &rusqlite::Connection) -> usize {
    let Ok(mut stmt) = conn.prepare("SELECT data FROM fleet_streams") else { return 0 };
    let Ok(rows) = stmt.query_map([], |r| r.get::<_, String>(0)) else { return 0 };
    let mut refs = std::collections::HashSet::new();
    for raw in rows.flatten() {
        let Ok(v) = serde_json::from_str::<serde_json::Value>(&raw) else { continue };
        for r in v.get("issues").and_then(serde_json::Value::as_array).into_iter().flatten() {
            if let Some(s) = r.as_str().map(|s| s.trim().trim_start_matches('#')) {
                if !s.is_empty() {
                    refs.insert(s.to_string());
                }
            }
        }
    }
    refs.len()
}

/// The per-project plan store for `key`: `plans/<key>.db`.
///
/// The plan store was RELOCATED OUT of the hub (#2996) so it survives folder churn — reading
/// `projects/<key>/plan.db` finds nothing on any current install (those hubs hold `error.db` only) and
/// would make this command silently report no work anywhere.
fn plan_db_for(key: &str) -> Option<std::path::PathBuf> {
    bsc_util::bsc_base_dir().map(|b| b.join("plans").join(format!("{key}.db")))
}

/// Every local project's issue counts, in one pass. Walks the projects dir; a project whose plan store
/// is missing or unreadable is dropped, so the result answers "what do we actually know".
pub fn collect_progress() -> Vec<ProjectProgress> {
    list_projects()
        .into_iter()
        .filter_map(|p| {
            let (done, total) = count_issues(&plan_db_for(&p.key)?)?;
            Some(ProjectProgress { key: p.key, done, total })
        })
        .collect()
}

/// `progress` — issue counts for every local project in ONE spawn (#4052). TSV `key\tdone\ttotal`,
/// or `--json` as an array of `{ key, done, total }`.
fn cmd_progress(args: &Args) -> Result<(), String> {
    let rows = collect_progress();
    if args.json {
        let arr: Vec<serde_json::Value> = rows
            .iter()
            .map(|r| serde_json::json!({ "key": r.key, "done": r.done, "total": r.total }))
            .collect();
        println!("{}", serde_json::to_string(&arr).unwrap_or_else(|_| "[]".into()));
    } else if rows.is_empty() {
        println!("(no local projects with a plan store)");
    } else {
        for r in &rows {
            println!("{}\t{}\t{}", r.key, r.done, r.total);
        }
    }
    Ok(())
}

/// `triaged list|set|clear` — the Glance triaged marker (#4088).
fn cmd_triaged(args: &Args, prog: &str) -> Result<(), String> {
    let conn = store::open()?;
    match args.positional.get(1).map(String::as_str).unwrap_or("list") {
        "list" => {
            let rows: Vec<serde_json::Value> = store::list(&conn)
                .into_iter()
                .filter_map(|r| r.triaged_at.map(|t| serde_json::json!({ "key": r.key, "triagedAt": t })))
                .collect();
            if args.json {
                println!("{}", serde_json::to_string(&rows).unwrap_or_else(|_| "[]".into()));
            } else if rows.is_empty() {
                println!("(no triaged projects)");
            } else {
                for r in &rows {
                    println!("{}	{}", r["key"].as_str().unwrap_or(""), r["triagedAt"]);
                }
            }
            Ok(())
        }
        verb @ ("set" | "clear") => {
            let key = args
                .positional
                .get(2)
                .ok_or_else(|| format!("usage: {prog} triaged {verb} <key>"))?;
            let now = bsc_util::now_ms();
            if verb == "set" {
                store::set_triaged(&conn, key, now)?;
            } else {
                store::clear_triaged(&conn, key, now)?;
            }
            // Print the row either way — including the no-op cases (already triaged / not triaged),
            // so a caller sees the resulting STATE rather than having to infer it from a bool.
            let row = store::get(&conn, key)
                .ok_or_else(|| format!("{prog} triaged {verb}: no such project '{key}'"))?;
            bsc_sqlite_util::print_json(&row, false);
            Ok(())
        }
        other => Err(format!("{prog} triaged: unknown verb '{other}' (list | set | clear)")),
    }
}

/// `architect list|set|clear` — which architect owns a project (#architects-own-projects).
/// `bsc project network list|set|clear` — a project's membership of a domain.
///
/// Mirrors [`cmd_architect`] deliberately, down to the unassigned-is-a-real-state handling: these are
/// the two supra-project relations and they should not need to be learned twice.
///
/// The network id is NOT checked against the network store, unlike the persona check `architect set`
/// performs. The asymmetry is intentional: an architect that does not exist detaches a project from
/// every architect edge in the graph and reads as a rendering bug, whereas a network that does not
/// exist just leaves the project out of every tab — visible, nameable, and one command from fixed.
fn cmd_network(args: &Args, prog: &str) -> Result<(), String> {
    let conn = store::open()?;
    match args.positional.get(1).map(String::as_str).unwrap_or("list") {
        "list" => {
            let rows: Vec<serde_json::Value> = store::list(&conn)
                .into_iter()
                .map(|r| serde_json::json!({ "key": r.key, "network": r.network }))
                .collect();
            if args.json {
                println!("{}", serde_json::to_string(&rows).unwrap_or_else(|_| "[]".into()));
            } else if rows.is_empty() {
                println!("(no projects)");
            } else {
                for r in &rows {
                    println!("{}\t{}", r["key"].as_str().unwrap_or(""), r["network"].as_str().unwrap_or("(unfiled)"));
                }
            }
            Ok(())
        }
        "set" => {
            let key = args.positional.get(2).ok_or_else(|| format!("usage: {prog} network set <key> <network>"))?;
            let network = args.positional.get(3).ok_or_else(|| format!("usage: {prog} network set <key> <network>"))?;
            if !store::set_network(&conn, key, network, bsc_util::now_ms())? {
                return Err(format!("{prog} network set: no such project '{key}' (list them with `{prog} list`)"));
            }
            print_network_row(&conn, key, prog)
        }
        "clear" => {
            // A no-op clear (already unfiled) is NOT an error — the caller asked for a state and gets
            // it. An absent KEY is different, and the read below catches it.
            let key = args.positional.get(2).ok_or_else(|| format!("usage: {prog} network clear <key>"))?;
            store::clear_network(&conn, key, bsc_util::now_ms())?;
            print_network_row(&conn, key, prog)
        }
        other => Err(format!("{prog} network: unknown verb '{other}' (list | set | clear)")),
    }
}

/// Print one project's `{ key, network }` after a write — the confirmation both mutating verbs end on.
fn print_network_row(conn: &rusqlite::Connection, key: &str, prog: &str) -> Result<(), String> {
    let row = store::get(conn, key)
        .ok_or_else(|| format!("{prog} network: no such project '{key}' (list them with `{prog} list`)"))?;
    println!("{}", serde_json::json!({ "key": row.key, "network": row.network }));
    Ok(())
}

fn cmd_architect(args: &Args, prog: &str) -> Result<(), String> {
    let conn = store::open()?;
    match args.positional.get(1).map(String::as_str).unwrap_or("list") {
        "list" => {
            // EVERY project, assigned or not — an unassigned one is a fact worth seeing, and it is
            // precisely the row a caller is looking for when a project is missing its architect edge.
            let rows: Vec<serde_json::Value> = store::list(&conn)
                .into_iter()
                .map(|r| serde_json::json!({ "key": r.key, "architect": r.architect }))
                .collect();
            if args.json {
                println!("{}", serde_json::to_string(&rows).unwrap_or_else(|_| "[]".into()));
            } else if rows.is_empty() {
                println!("(no projects)");
            } else {
                for r in &rows {
                    println!("{}\t{}", r["key"].as_str().unwrap_or(""), r["architect"].as_str().unwrap_or("(unassigned)"));
                }
            }
            Ok(())
        }
        "set" => {
            let key = args.positional.get(2).ok_or_else(|| format!("usage: {prog} architect set <key> <persona>"))?;
            let persona = args.positional.get(3).ok_or_else(|| format!("usage: {prog} architect set <key> <persona>"))?;
            check_architect_persona(persona)?;
            if !store::set_architect(&conn, key, persona, bsc_util::now_ms())? {
                return Err(format!("{prog} architect set: no such project '{key}' (list them with `{prog} list`)"));
            }
            print_architect_row(&conn, key, prog)
        }
        "clear" => {
            let key = args.positional.get(2).ok_or_else(|| format!("usage: {prog} architect clear <key>"))?;
            // A no-op clear (already unassigned) is NOT an error — the caller asked for a state, and
            // that state is what it gets. An absent KEY is different, and is caught by the read below.
            store::clear_architect(&conn, key, bsc_util::now_ms())?;
            print_architect_row(&conn, key, prog)
        }
        other => Err(format!("{prog} architect: unknown verb '{other}' (list | set | clear)")),
    }
}

/// Print the resulting `{ key, architect }` row, so a caller sees the STATE rather than inferring it
/// from an exit code. Errors when the key names no project.
fn print_architect_row(conn: &rusqlite::Connection, key: &str, prog: &str) -> Result<(), String> {
    let row = store::get(conn, key)
        .ok_or_else(|| format!("{prog} architect: no such project '{key}' (list them with `{prog} list`)"))?;
    println!("{}", serde_json::json!({ "key": row.key, "architect": row.architect }));
    Ok(())
}

/// Refuse a persona that is not an architect (#architects-own-projects).
///
/// WHY VALIDATE AT ALL, when `link add` happily takes free-text endpoints: a bad endpoint draws a
/// visibly wrong edge, whereas a bad architect id draws NOTHING — the project silently detaches from
/// every architect and reads as a rendering bug rather than a typo. The cheapest place to catch it is
/// the moment it is typed.
///
/// CANNOT-VERIFY IS NOT INVALID. The persona store is seeded by the desktop on first hydrate, so a
/// fresh install (or any environment where the app has never run) has an EMPTY store — refusing there
/// would make a correct assignment impossible on exactly the machines that need to bootstrap. An empty
/// or unreadable store therefore skips the check; a populated one enforces it.
fn check_architect_persona(persona: &str) -> Result<(), String> {
    let Some(base) = bsc_util::bsc_base_dir() else { return Ok(()) };
    let personas = bsc_json_store::Store::new(base.join("personas"), "persona").list();
    if personas.is_empty() {
        return Ok(()); // never seeded — cannot verify, so do not pretend to
    }
    let mut found_role: Option<String> = None;
    for raw in &personas {
        let Ok(v) = serde_json::from_str::<serde_json::Value>(raw) else { continue };
        if v.get("id").and_then(|i| i.as_str()) == Some(persona) {
            found_role = Some(v.get("role").and_then(|r| r.as_str()).unwrap_or("").to_string());
            break;
        }
    }
    match found_role.as_deref() {
        Some("architect") => Ok(()),
        Some(role) => Err(format!(
            "architect set: persona '{persona}' has role '{role}', not 'architect'.\n\
             Only an architect can own projects — list the candidates with `bsc persona list`."
        )),
        None => Err(format!(
            "architect set: no persona '{persona}' (list them with `bsc persona list`).\n\
             An assignment to a persona that does not exist would detach the project from every \
             architect in the graph, which reads as a rendering bug rather than a typo."
        )),
    }
}

/// `published get|set <key>` — read or set a project's in-place `.published` marker.
