    /// `architect list|set|clear` (#architects-own-projects) — the ONLY surface that assigns a project
    /// to an architect, since there is deliberately no picker in the UI.
    #[test]
    fn network_dispatch_files_moves_and_unfiles() {
        crate::testhome::with_home(|home| {
            std::env::set_var("BSC_PROJECT_DB", home.join("projects-net.db"));
            let conn = store::open().unwrap();
            store::upsert(&conn, &ProjectRow {
                key: "wan-relay".into(), title: "WAN Relay".into(), pitch: String::new(),
                blueprint: None, category: None, state: "drafted".into(),
                created_at: 1, updated_at: 1, triaged_at: None, architect: None, network: None,
            }).unwrap();
            drop(conn);

            run(vec!["network".into(), "set".into(), "wan-relay".into(), "network-kitchen".into()], "bsc project").unwrap();
            let conn = store::open().unwrap();
            assert_eq!(store::get(&conn, "wan-relay").unwrap().network.as_deref(), Some("network-kitchen"));
            drop(conn);

            // Moving between domains is the normal case, not a history rewrite.
            run(vec!["network".into(), "set".into(), "wan-relay".into(), "network-finance".into()], "bsc project").unwrap();
            let conn = store::open().unwrap();
            assert_eq!(store::get(&conn, "wan-relay").unwrap().network.as_deref(), Some("network-finance"));
            drop(conn);

            run(vec!["network".into(), "clear".into(), "wan-relay".into()], "bsc project").unwrap();
            let conn = store::open().unwrap();
            assert_eq!(store::get(&conn, "wan-relay").unwrap().network, None);
            drop(conn);

            // A network that does not exist is ACCEPTED — unlike `architect set`, which refuses an
            // unknown persona. See `cmd_network`'s doc for why the two differ.
            run(vec!["network".into(), "set".into(), "wan-relay".into(), "network-ghost".into()], "bsc project").unwrap();
            let conn = store::open().unwrap();
            assert_eq!(store::get(&conn, "wan-relay").unwrap().network.as_deref(), Some("network-ghost"));
            drop(conn);

            run(vec!["network".into(), "list".into(), "--json".into()], "bsc project").unwrap();
            run(vec!["network".into(), "list".into()], "bsc project").unwrap();
            assert!(run(vec!["network".into(), "nope".into()], "bsc project").is_err());
            assert!(run(vec!["network".into(), "set".into(), "ghost".into(), "network-kitchen".into()], "bsc project").is_err(),
                    "an absent project key is an error, unlike an absent network");
            std::env::remove_var("BSC_PROJECT_DB");
        });
    }

