                    "new".into(), "Acme".into(),
                    "--pitch".into(), "a thing that does stuff".into(),
                    "--blueprint".into(), "crm".into(),
                ],
                "bsc project",
            )
            .unwrap();
            let conn = store::open().unwrap();
            let row = store::get(&conn, "acme").unwrap();
            assert_eq!(row.pitch, "a thing that does stuff");
            assert_eq!(row.blueprint.as_deref(), Some("crm"));
        });
    }

    /// The collision refusal. A key is FROZEN at creation, so adopting the existing project would
    /// hand the caller someone else's plan under a name it believes it just created — and
    /// overwriting would destroy it. Refusing, and naming what is there, is the same choice the UI's
    /// collision modal offers.
    #[test]
    fn new_refuses_a_name_whose_slug_is_taken_rather_than_adopting_it() {
        crate::testhome::with_home(|home| {
            std::env::set_var("BSC_PROJECT_DB", home.join("projects-new-collide.db"));
            run(vec!["new".into(), "Video Game".into()], "bsc project").unwrap();

            // The SAME name, and a different name with the same slug — both are the one key.
            for name in ["Video Game", "video game", "VIDEO  GAME!"] {
                let err = run(vec!["new".into(), name.into()], "bsc project").unwrap_err();
                assert!(err.contains("already exists"), "{name}: {err}");
                assert!(err.contains("video-game"), "the refusal names the key: {err}");
            }

            // And the original is untouched — not re-stamped, not re-titled.
            let conn = store::open().unwrap();
            assert_eq!(store::get(&conn, "video-game").unwrap().title, "Video Game");
        });
    }

    /// A free-text name cannot name a directory outside the projects root, and cannot create a row
    /// under a key that would. This is the containment the whole verb rests on.
    #[test]
    fn new_contains_a_hostile_name_inside_the_projects_root() {
        crate::testhome::with_home(|home| {
            std::env::set_var("BSC_PROJECT_DB", home.join("projects-new-hostile.db"));
            run(vec!["new".into(), "../../etc/passwd".into()], "bsc project").unwrap();

            let conn = store::open().unwrap();
            let rows = store::list(&conn);
            assert_eq!(rows.len(), 1);
            assert_eq!(rows[0].key, "etc-passwd", "traversal is slugged away, not honoured");
            assert!(!rows[0].key.contains(".."));
            // The title keeps what the caller actually said — the KEY is sanitised, not the record.
            assert_eq!(rows[0].title, "../../etc/passwd");
        });
    }

    #[test]
    fn resolve_network_takes_the_creating_architects_own_network() {
        // The whole point: an architect's project lands in that architect's domain without the
        // charter having to remember a flag. `network-<slug>:architect` is the pane grammar
        // `bsc network` mints and `bsc_session::network_architect_slug` validates.
        assert_eq!(
            resolve_network(None, Some("network-finance:architect".into())),
            Some("network-finance".to_string())
        );
    }

    #[test]
    fn resolve_network_refuses_a_pane_that_is_not_a_network_architect() {
        // `BSC_AUDIT_PANE` is `<key>:<tail>` for EVERY session in the app, so without both halves of
        // the check a worker would file its project into a "network" named after its project. Each of
        // these is a real pane id from somewhere in the app.
        for pane in [
            "studio-code:auth",              // a worker — key is a project, tail is a stream
            "studio-code:director",          // a director
            "studio-code:repo:triage",       // triage
            "teams-studio:architect",        // an architect, but of a STUDIO, not a network
            "network-finance:director",      // a network key, but not the architect
            "network-:architect",            // the `network-` prefix with no slug behind it
            "network-finance",               // no tail at all
        ] {
            assert_eq!(resolve_network(None, Some(pane.into())), None, "{pane} must not name a network");
        }
    }

    #[test]
    fn resolve_network_prefers_an_explicit_flag_and_ignores_a_blank_one() {
        // `--network ""` means "I passed nothing" and must fall THROUGH to the pane rather than
        // short-circuiting with a blank — the same rule `resolve_origin` applies to `--from`.
        assert_eq!(
            resolve_network(Some("network-legal".into()), Some("network-finance:architect".into())),
            Some("network-legal".to_string())
        );
        assert_eq!(
            resolve_network(Some("  ".into()), Some("network-finance:architect".into())),
            Some("network-finance".to_string())
        );
        assert_eq!(resolve_network(Some("?".into()), None), None);
        assert_eq!(resolve_network(None, None), None);
    }

    #[test]
    fn new_needs_a_non_empty_name() {
        crate::testhome::with_home(|home| {
            std::env::set_var("BSC_PROJECT_DB", home.join("projects-new-empty.db"));
            for args in [vec!["new".into()], vec!["new".into(), "   ".into()]] {
                let err = run(args, "bsc project").unwrap_err();
                assert!(err.contains("usage:"), "{err}");
            }
            let conn = store::open().unwrap();
            assert!(store::list(&conn).is_empty(), "a refused create writes nothing");
        });
    }

    #[test]
    fn db_cli_dispatch_reads_and_mutates_a_temp_store() {
        crate::testhome::with_home(|home| {
            // Point the store at a temp file — `$BSC_PROJECT_DB` is checked first by default_path,
            // so this is deterministic regardless of the HOME/USERPROFILE precedence. `with_home`
            // holds the process-global env lock for the whole closure, so this set is race-free.
            let db = home.join("projects-cli-test.db");
            std::env::set_var("BSC_PROJECT_DB", &db);

            // Seed a row directly (the `add` verb reads real stdin, which a unit test can't drive).
            let conn = store::open().unwrap();
            store::upsert(
                &conn,
                &ProjectRow {
                    key: "alpha".into(),
                    title: "Alpha".into(),
                    pitch: String::new(),
                    blueprint: None,
                    category: None,
                    state: "drafted".into(),
                    created_at: 1,
                    updated_at: 1,
                    triaged_at: None,
                    architect: None,
                    network: None,
                },
            )
            .unwrap();
            drop(conn);

            // The read verbs dispatch + open the same store without error.
            run(vec!["db".into(), "get".into(), "alpha".into()], "bsc project").unwrap();
            run(vec!["db".into(), "list".into()], "bsc project").unwrap();

            // `state` hits an existing row (and actually persists the transition)…
            run(vec!["db".into(), "state".into(), "alpha".into(), "published".into()], "bsc project").unwrap();
            let conn = store::open().unwrap();
            assert_eq!(store::get(&conn, "alpha").unwrap().state, "published");
            drop(conn);
            // …and errors on an absent key.
            assert!(run(vec!["db".into(), "state".into(), "ghost".into(), "x".into()], "bsc project").is_err());

            // `remove` deletes the row; an unknown sub errors with the db help.
            run(vec!["db".into(), "remove".into(), "alpha".into()], "bsc project").unwrap();
            let conn = store::open().unwrap();
            assert!(store::get(&conn, "alpha").is_none());
            drop(conn);
            let err = run(vec!["db".into(), "nope".into()], "bsc project").unwrap_err();
            assert!(err.contains("db"));

            std::env::remove_var("BSC_PROJECT_DB");
        });
    }
}

tests.src:
//! The `bsc project` subcommand (#1877) — the agent-facing CLI over the cross-project hub layout
//! (#1720). Unlike `bsc plan` (scoped to ONE project's plan.db), this lists every local project
//! under `~/.base-studio-code/projects/` and reads/sets the in-place `.published` marker.
//!
//! Extracted from the old `bsc-project` binary so the unified `bsc` umbrella dispatches into it via
//! [`run`]; the per-command help (#1762) is unchanged:
//!   bsc project help            # compact menu
//!   bsc project published help  # detailed help for ONE command
//!   bsc project <cmd> help      # same, after any command

use crate::store::{self, ProjectRow};
use crate::{
    add_contract, is_published, link_row_json, list_projects, load_github_state, load_links,
    mark_published, remove_link, save_github_state, update_contract, ContractPatch, ContractTarget,
};
use bsc_cli_util::CmdDoc;
use serde::Deserialize;

/// The stdin shape `db add` reads — one JSON object. `pitch` defaults to `""` and `state` to
/// `"drafted"` when absent; `blueprint`/`category` are nullable. Timestamps are NOT read from stdin —
/// the CLI stamps `createdAt`/`updatedAt` itself (epoch millis).
#[derive(Deserialize)]
#[serde(rename_all = "camelCase")]
struct AddInput {
    key: String,
    title: String,
    #[serde(default)]
    pitch: String,
    blueprint: Option<String>,
    category: Option<String>,
    state: Option<String>,
}

const TAGLINE: &str =
    "the cross-project hub lifecycle — list local projects + the .published marker (#1720)";

/// The command catalog — drives both dispatch and the shared help system. One detailed `usage` block
/// per top-level command keeps the overview tiny and the detail one-fetch-away.
const COMMANDS: &[CmdDoc] = &[
    CmdDoc {
        name: "new",
        summary: "create a project from a NAME — creation begins where the conversation is",
        usage: "\
USAGE:
  bsc project new \"<name>\" [--pitch \"<text>\"] [--blueprint <id>] [--json|--pretty]

Creates a project as a DRAFT, so a conversation that arrives at \"build this\" does not have to leave
the conversation to begin (#architect-starts-a-new-project).

THE NAME BECOMES THE KEY, and the key is FROZEN at creation. `projectSlug(name)` — lowercase,
[a-z0-9-], capped at 60 — names the hub, its plan.db, its worktrees, its pane ids and its board
project, for the life of the project. Renaming later is display-only; the folder keeps its birth-slug.

THE SLUG IS ALSO THE CONTAINMENT. This is the one verb here whose argument is genuinely free text, so
the rule is what keeps it inside `projects/`: `../../etc/passwd` becomes `etc-passwd`, `..` becomes
`project`. No name can name a directory outside the projects root.

A NAME WHOSE SLUG ALREADY EXISTS IS REFUSED, naming what is already there — the same choice the UI's
collision modal offers, rather than silently adopting or overwriting someone else's hub. Two projects
genuinely wanting one name is a decision for a person; pick a different name and run it again.

The new project appears in the app's project list without a restart: the list reads this same store.",
    },
    CmdDoc {
        name: "list",
        summary: "key + published + path for every local project",
        usage: "\
USAGE:
  bsc project list [--json]

Prints one row per local project under ~/.base-studio-code/projects/ — its key, whether it is
published, and its absolute path. TSV by default; --json emits an array of { key, published, path }.",
    },
    CmdDoc {
        name: "progress",
        summary: "issue counts (done/total) for EVERY local project, in one read (#4052)",
        usage: "\
USAGE:
  bsc project progress [--json]

Prints one row per local project that has a plan store - its key, how many of its issues are done
(complete|verified) and how many it has in total. TSV by default; --json emits an array of
{ key, done, total }.

The plan store is plans/<key>.db, NOT projects/<key>/plan.db - it was relocated out of the hub in
#2996 so it survives folder churn.

A project with no plan store, or whose store has no issues table yet, is OMITTED entirely: absent
and \"0 of 0\" are different facts, and only the caller knows which one it wants to render.

This exists so a caller wanting every project's progress makes ONE process spawn instead of one per
project. Opening N SQLite files inside one process costs milliseconds; spawning N processes has
repeatedly cost this app whole seconds (#3908 / #3912 / #3944 / #3954).",
    },
    CmdDoc {
        name: "triaged",
        summary: "the Glance TRIAGED marker — list / set / clear (#4088)",
        usage: "USAGE:
  bsc project triaged list [--json]   # every triaged project + when (epoch ms)
  bsc project triaged set <key>       # mark it triaged; prints the row
  bsc project triaged clear <key>     # unmark it; prints the row

The triaged marker gates the Glance project network (#2541): an UNTRIAGED project does not appear
there at all. It is stamped by launching triage or a fleet, and now lives in projects.db so a live
session can inspect and repair it — before #4088 it existed only inside the desktop's app-state.json,
where no command could reach it, it was lost on an app-state reset, and a project missing from Glance
could only be diagnosed by reading a raw zustand blob.

`set` is IDEMPOTENT: an already-triaged project keeps its FIRST timestamp.",
    },
    CmdDoc {
        name: "architect",
        summary: "which ARCHITECT owns a project — list / set / clear (#architects-own-projects)",
        usage: "USAGE:
  bsc project architect list [--json]        # every project + the architect that owns it
  bsc project architect set <key> <persona>  # assign <key> to an architect persona; prints the row
  bsc project architect clear <key>          # unassign it; prints the row

An architect OWNS a set of projects rather than all of them — so a networking architect can hold the
LAN/WAN applications while another holds the rest. The Glance project network draws each project
edged to ITS architect, and this command is the ONLY way to change that: there is no picker in the
UI, by design. The AI configures ownership.

<persona> is a persona id from `bsc persona list` whose role is `architect`. A persona that does not
exist, or whose role is something else, is REFUSED rather than stored — an assignment to nobody would
silently drop the project off its architect in the graph and look like a rendering bug.

UNASSIGNED IS A REAL STATE, not a broken one. A project with no architect edges to the sole architect
when there is exactly one (so a single-architect setup looks exactly as it always did), and to none
once there are several — at which point the graph is telling you to say which.

`set` is not idempotent-by-first-write the way `triaged set` is: ownership is a current fact that
moves, so re-assigning to a different architect is the normal case rather than a history rewrite.",
    },
    CmdDoc {
        name: "published",
        summary: "read or set a project's .published marker",
        usage: "\
USAGE:
  bsc project published get <key>     # print whether <key> is published
  bsc project published set <key>     # mark <key> published (writes the in-place .published marker)

Published-ness is the in-place .published marker under the project hub (#922) — setting it never
moves the hub directory. For a single project's plan + prose, use `bsc plan` instead.",
    },
    CmdDoc {
        name: "link",
        summary: "list / add / set / remove inter-app contracts (the Glance network edges, #2253/#3786)",
        usage: "\
USAGE:
  bsc project link list [--json]              # every contract (--json includes the target endpoint)
  bsc project link add <from> <to> <kind> [target flags]   # add from->to over api|data|events (idempotent; prints the id)
  bsc project link set <id> [--kind <k>] [target flags]    # MODIFY an existing contract; prints the stored row
  bsc project link remove <id>                # remove by id (id is \"<from>><to>:<kind>\")

  target flags for `add` and `set` (#3786 — default is another project):
    --target-type project|service|mcp   # what <to> is: another project (default), an external service, or an mcp server
    --name <name>                       # display name of the external endpoint
    --url <url>                         # endpoint URL (an http service / mcp server)
    --app-type <type>                   # endpoint app type (api | serverless | static | …), shown on the Glance node

A contract records that project <from> depends on / consumes <to> over <kind> (api | data | events).
<to> is another project by default, or an external service / mcp server via --target-type. Global (not
tied to one plan.db); stored in ~/.base-studio-code/project-links.json. Agents read `link list --json`
to learn what their project consumes; the desktop Glance draws each contract as an edge (external
service/mcp targets render as their own contract node).

MODIFYING one is `set`, not a second `add`: `add` is idempotent BY ID, so re-adding an existing
contract with different flags is a silent no-op. `set` takes the id and patches only the flags you
pass — an EMPTY value clears a descriptor (--url \"\"), and an absent flag leaves that field alone.

  · `set` on an id that does not exist is an ERROR, never a create. Run `link list` first.
  · --kind RE-KEYS the contract, because the id derives from it; the new id is printed. A re-key onto
    an id that already exists is refused rather than merging the two.
  · `set` always prints the stored row as JSON (like `db`), since a re-key changes the id.

  e.g.  bsc project link add my-app postgres data --target-type mcp --app-type serverless
        bsc project link add my-app stripe api --target-type service --url https://api.stripe.com --app-type api
        bsc project link set \"my-app>stripe:api\" --url https://api.stripe.com/v2
        bsc project link set \"my-app>billing:api\" --kind events        # re-keys to my-app>billing:events",
    },
    CmdDoc {
        name: "github-state",
        summary: "read or replace the persisted last-known GitHub board state (#2446)",
        usage: "\
USAGE:
  bsc project github-state [get]      # print the persisted board-state JSON
  bsc project github-state set        # replace it wholesale from a JSON body on stdin

The desktop app mirrors its last successful GitHub projects fetch here
(~/.base-studio-code/github-state.json) so the last-known board state is reachable offline:
{ records: [{ id, number, title, shortDescription, url, closed, updatedAt, itemsTotalCount,
openCount, closedCount, repos }, ...], fetchedAt: <epoch ms> }. `set` expects that whole envelope
on stdin and rejects anything else, so a malformed write never clobbers the last good state.",
    },
    CmdDoc {
        name: "db",
        summary: "the durable projects store — add/get/list/remove/state over projects.db (#2995)",
        usage: "\
USAGE:
  bsc project db add                  # upsert one project from a JSON object on stdin; prints the stored row
  bsc project db get <key>            # print the project row JSON, or null
  bsc project db list                 # print a JSON array of every project row
  bsc project db remove <key>         # delete by key; prints { \"removed\": <bool> }
  bsc project db state <key> <state>  # set the lifecycle state; prints the row, or errors if <key> is absent

The durable source of truth for what projects/drafts exist — SQLite at ~/.base-studio-code/projects.db
(override with $BSC_PROJECT_DB), separate from the disk-scan `list` (which walks the on-disk hubs).
`add` reads { key, title, pitch?, blueprint?, category?, state? } (pitch defaults \"\", state \"drafted\");
it stamps createdAt on a NEW key and preserves it on an update, always bumping updatedAt. Every row is
{ key, title, pitch, blueprint, category, state, createdAt, updatedAt } (blueprint/category nullable).",
    },
];

/// Parsed global flags + the `link add`/`link set` contract-target flags (#3786) + leftover positional
/// args.
struct Args {
    json: bool,
    /// `--kind api|data|events` — `link set` only: the contract kind, which RE-KEYS the link. `add`
    /// takes its kind positionally, so this flag never applies there.
    kind: Option<String>,
    /// `--target-type project|service|mcp` (default project) — the endpoint kind a contract points at.
    target_type: Option<String>,
    /// `--name` — display name of an external endpoint.
    name: Option<String>,
    /// `--url` — the endpoint URL.
    url: Option<String>,
    /// `--app-type` — the endpoint's application-architecture discriminator (api | serverless | …).
    app_type: Option<String>,
    /// `--pitch` — `new` only: the one-line brief the project starts from.
    pitch: Option<String>,
    /// `--blueprint` — `new` only: the blueprint id that seeds the plan.
    blueprint: Option<String>,
    positional: Vec<String>,
}

/// A flag value that is actually a value: trimmed, with an empty one dropped to `None`. `link add`
/// uses it so an empty descriptor is stored as ABSENT rather than as `""` — the same normalization
/// `update_contract` applies when a `set` clears one, so the two verbs cannot disagree about what an
/// empty flag means.
fn nonempty(v: &Option<String>) -> Option<String> {
    v.as_deref().map(str::trim).filter(|s| !s.is_empty()).map(str::to_string)
}

fn parse_args(raw: Vec<String>) -> Result<Args, String> {
    let mut a = Args { json: false, kind: None, target_type: None, name: None, url: None, app_type: None, pitch: None, blueprint: None, positional: Vec::new() };
    // A value flag consumes the NEXT token, so iterate with an index rather than a plain for-each.
    let mut it = raw.into_iter();
    while let Some(arg) = it.next() {
        // The value flags (#3786) take `<flag> <value>`; missing the value is an error.
        let mut take = |flag: &str| it.next().ok_or_else(|| format!("{flag} needs a value"));
        match arg.as_str() {
            "--json" => a.json = true,
            // `-h`/`--help` route to the help command (anywhere on the line).
            "-h" | "--help" => a.positional.insert(0, "help".into()),
            "--kind" => a.kind = Some(take("--kind")?),
            "--target-type" => a.target_type = Some(take("--target-type")?),
            "--name" => a.name = Some(take("--name")?),
            "--url" => a.url = Some(take("--url")?),
            "--app-type" => a.app_type = Some(take("--app-type")?),
            "--pitch" => a.pitch = Some(take("--pitch")?),
            "--blueprint" => a.blueprint = Some(take("--blueprint")?),
            other if other.starts_with("--") => return Err(format!("unknown flag '{other}'")),
            _ => a.positional.push(arg),
        }
    }
    Ok(a)
}

/// The `project` subcommand entrypoint: `args` is everything after `bsc project`; `prog` is the
/// display name for help/errors (`"bsc project"` from the umbrella, `"bsc-project"` from the legacy
/// shim). Handles help (no command / `help` / `help <cmd>` / `<cmd> help`) before any store read.
pub fn run(args: Vec<String>, prog: &str) -> Result<(), String> {
    let args = parse_args(args)?;
    let cmd = args.positional.first().cloned().unwrap_or_default();

    if bsc_cli_util::handle_help(prog, TAGLINE, COMMANDS, &args.positional) {
        return Ok(());
    }

    match cmd.as_str() {
        "new" => cmd_new(&args, prog),
        "list" => cmd_list(&args),
        "progress" => cmd_progress(&args),
        "triaged" => cmd_triaged(&args, prog),
        "architect" => cmd_architect(&args, prog),
        "published" => cmd_published(&args, prog),
        "link" => cmd_link(&args, prog),
        "github-state" => cmd_github_state(&args, prog),
        "db" => cmd_db(&args, prog),
        other => Err(bsc_cli_util::unknown_command(prog, TAGLINE, COMMANDS, other)),
    }
}

/// `new "<name>"` — create a project from a name (#architect-starts-a-new-project).
///
/// The whole verb is: derive the frozen key, refuse a collision, write a drafted row. It deliberately
/// does NOT scaffold the hub directory — `setup_workspaces` owns that and runs when the project is
/// actually opened, so creating one from a conversation leaves no empty folder behind if the idea is
/// dropped. The durable row is what makes it a project; the folder is what makes it a workspace.
fn cmd_new(args: &Args, prog: &str) -> Result<(), String> {
    let name = args
        .positional
        .get(1)
        .map(|s| s.trim())
        .filter(|s| !s.is_empty())
        .ok_or_else(|| format!("usage: {prog} new \"<name>\" [--pitch \"<text>\"] [--blueprint <id>]"))?;

    let key = crate::project_slug(name);
    let conn = store::open()?;

    // TWO collision checks, because there are two places a project can already exist and either one
    // makes this name taken. The store row is the durable identity; the hub is what a PRE-store
    // project (or one whose row was removed) left on disk. Adopting either silently would hand the
    // caller someone else's plan under a name it believes it just created.
    if let Some(existing) = store::get(&conn, &key) {
        return Err(format!(
            "'{name}' slugs to '{key}', which already exists: \"{}\" ({}).\n\
             Pick a different name — a project's key is frozen at creation, so two projects cannot \
             share one.",
            existing.title, existing.state
        ));
    }
    if crate::project_dir(&key).is_some_and(|d| d.exists()) {
        return Err(format!(
            "'{name}' slugs to '{key}', and a project hub already exists at that path.\n\
             Pick a different name, or open the existing project."
        ));
    }

    let now = bsc_util::now_ms();
    let row = ProjectRow {
        key: key.clone(),
        title: name.to_string(),
        pitch: args.pitch.clone().unwrap_or_default(),
        blueprint: args.blueprint.clone(),
        category: None,
        // `drafted` is the honest state: nothing is planned, published or on disk yet.
        state: "drafted".into(),
        triaged_at: None,
        architect: None,
        created_at: now,
        updated_at: now,
    };
    store::upsert(&conn, &row)?;
    let stored = store::get(&conn, &key).ok_or("project new: row vanished after upsert")?;

    if args.json {
        bsc_sqlite_util::print_json(&stored, false);
    } else {
        println!("{key}");
    }
    Ok(())
}

/// `list` — every local project: key + published + absolute path. Human TSV (one row each) or, with
/// `--json`, an array of `{ key, published, path }`.
fn cmd_list(args: &Args) -> Result<(), String> {
    let projects = list_projects();
    if args.json {
        let arr: Vec<serde_json::Value> = projects
            .iter()
            .map(|p| serde_json::json!({ "key": p.key, "published": p.published, "path": p.path.to_string_lossy() }))
            .collect();
        println!("{}", serde_json::to_string(&arr).unwrap_or_else(|_| "[]".into()));
    } else if projects.is_empty() {
        println!("(no local projects)");
    } else {
        for p in &projects {
            println!(
                "{}\t{}\t{}",
                p.key,
                if p.published { "published" } else { "unpublished" },
                p.path.to_string_lossy()
            );
        }
    }
    Ok(())
}

/// One project's issue completion, as counts (#4052). Counts, never a ratio — a caller can render
/// "3/7" as readily as a bar, and neither has to reconstruct the other.
#[derive(Debug, PartialEq, Eq)]
pub struct ProjectProgress {
    pub key: String,
    pub done: usize,
    pub total: usize,
}

/// Count one plan.db's issues as `(done, total)`. `None` when the file has no readable `issues`
/// table — a hub scaffolded but never planned, which is ABSENT rather than empty (see `cmd_progress`).
///
/// Read-only + `busy_timeout`'d through the shared opener, because a live fleet is writing these very
/// rows while this reads them; a plain `open` would surface a transient lock as a hard error and
/// blank a project that is merely busy.
fn count_issues(db: &std::path::Path) -> Option<(usize, usize)> {
    if !db.is_file() {
        return None;
    }
    let conn = bsc_sqlite_util::open_db(db).ok()?;
    let mut stmt = conn.prepare("SELECT status, COUNT(*) FROM issues GROUP BY status").ok()?;
    let rows = stmt.query_map([], |r| Ok((r.get::<_, String>(0)?, r.get::<_, i64>(1)?))).ok()?;
    let (mut done, mut total) = (0usize, 0usize);
    for row in rows.flatten() {
        let (status, n) = (row.0, row.1.max(0) as usize);
        total += n;
        // An unknown status counts toward the DENOMINATOR only — `is_done_status` is deliberately
        // conservative, so a typo can never inflate a completion count.
        if plandb::is_done_status(&status) {
            done += n;
        }
    }
    // #4118: a project whose `issues` table is EMPTY still owns work — the fleet's streams carry it as
    // GitHub refs, which is the ONLY record for a fleet assembled outside a full planner run (measured:
    // 40 streams, 56 refs, 0 issue rows). Reporting 0/0 there is not "no progress", it is "no data", and
    // the two are indistinguishable to every caller: a total of 0 suppresses the bar entirely, so the
    // project reads as owning nothing. Fall back to the refs so the DENOMINATOR is real.
    //
    // `done` stays 0 on this path on purpose. The refs are GitHub issue numbers and this is a local
    // SQLite read with no network — claiming completion it cannot verify would be the one error worse
    // than showing none. The frontend overlays real closed-ness (#4102/#4103) where it has a token.
    if total == 0 {
        return Some((0, count_stream_refs(&conn)));
    }
    Some((done, total))
}

/// How many distinct issue refs this project's fleet streams OWN (#4118).
///
/// `fleet_streams.data` is a JSON blob per stream carrying `issues: ["#3898", …]`. De-duplicated across
/// streams: two streams naming the same ref are one piece of work, and double-counting would inflate
/// every denominator on the board.
fn count_stream_refs(conn: &rusqlite::Connection) -> usize {
    let Ok(mut stmt) = conn.prepare("SELECT data FROM fleet_streams") else { return 0 };
    let Ok(rows) = stmt.query_map([], |r| r.get::<_, String>(0)) else { return 0 };
    let mut refs = std::collections::HashSet::new();
    for raw in rows.flatten() {
        let Ok(v) = serde_json::from_str::<serde_json::Value>(&raw) else { continue };
        for r in v.get("issues").and_then(serde_json::Value::as_array).into_iter().flatten() {
            if let Some(s) = r.as_str().map(|s| s.trim().trim_start_matches('#')) {
                if !s.is_empty() {
                    refs.insert(s.to_string());
                }
            }
        }
    }
    refs.len()
}

/// The per-project plan store for `key`: `plans/<key>.db`.
///
/// The plan store was RELOCATED OUT of the hub (#2996) so it survives folder churn — reading
/// `projects/<key>/plan.db` finds nothing on any current install (those hubs hold `error.db` only) and
/// would make this command silently report no work anywhere.
fn plan_db_for(key: &str) -> Option<std::path::PathBuf> {
    bsc_util::bsc_base_dir().map(|b| b.join("plans").join(format!("{key}.db")))
}

/// Every local project's issue counts, in one pass. Walks the projects dir; a project whose plan store
/// is missing or unreadable is dropped, so the result answers "what do we actually know".
pub fn collect_progress() -> Vec<ProjectProgress> {
    list_projects()
        .into_iter()
        .filter_map(|p| {
            let (done, total) = count_issues(&plan_db_for(&p.key)?)?;
            Some(ProjectProgress { key: p.key, done, total })
        })
        .collect()
}

/// `progress` — issue counts for every local project in ONE spawn (#4052). TSV `key\tdone\ttotal`,
/// or `--json` as an array of `{ key, done, total }`.
fn cmd_progress(args: &Args) -> Result<(), String> {
    let rows = collect_progress();
    if args.json {
        let arr: Vec<serde_json::Value> = rows
            .iter()
            .map(|r| serde_json::json!({ "key": r.key, "done": r.done, "total": r.total }))
            .collect();
        println!("{}", serde_json::to_string(&arr).unwrap_or_else(|_| "[]".into()));
    } else if rows.is_empty() {
        println!("(no local projects with a plan store)");
    } else {
        for r in &rows {
            println!("{}\t{}\t{}", r.key, r.done, r.total);
        }
    }
    Ok(())
}

/// `triaged list|set|clear` — the Glance triaged marker (#4088).
fn cmd_triaged(args: &Args, prog: &str) -> Result<(), String> {
    let conn = store::open()?;
    match args.positional.get(1).map(String::as_str).unwrap_or("list") {
        "list" => {
            let rows: Vec<serde_json::Value> = store::list(&conn)
                .into_iter()
                .filter_map(|r| r.triaged_at.map(|t| serde_json::json!({ "key": r.key, "triagedAt": t })))
                .collect();
            if args.json {
                println!("{}", serde_json::to_string(&rows).unwrap_or_else(|_| "[]".into()));
            } else if rows.is_empty() {
                println!("(no triaged projects)");
            } else {
                for r in &rows {
                    println!("{}	{}", r["key"].as_str().unwrap_or(""), r["triagedAt"]);
                }
            }
            Ok(())
        }
        verb @ ("set" | "clear") => {
            let key = args
                .positional
                .get(2)
                .ok_or_else(|| format!("usage: {prog} triaged {verb} <key>"))?;
            let now = bsc_util::now_ms();
            if verb == "set" {
                store::set_triaged(&conn, key, now)?;
            } else {
                store::clear_triaged(&conn, key, now)?;
            }
            // Print the row either way — including the no-op cases (already triaged / not triaged),
            // so a caller sees the resulting STATE rather than having to infer it from a bool.
            let row = store::get(&conn, key)
                .ok_or_else(|| format!("{prog} triaged {verb}: no such project '{key}'"))?;
            bsc_sqlite_util::print_json(&row, false);
            Ok(())
        }
        other => Err(format!("{prog} triaged: unknown verb '{other}' (list | set | clear)")),
    }
}

/// `architect list|set|clear` — which architect owns a project (#architects-own-projects).
fn cmd_architect(args: &Args, prog: &str) -> Result<(), String> {
    let conn = store::open()?;
    match args.positional.get(1).map(String::as_str).unwrap_or("list") {
        "list" => {
            // EVERY project, assigned or not — an unassigned one is a fact worth seeing, and it is
            // precisely the row a caller is looking for when a project is missing its architect edge.
            let rows: Vec<serde_json::Value> = store::list(&conn)
                .into_iter()
                .map(|r| serde_json::json!({ "key": r.key, "architect": r.architect }))
                .collect();
            if args.json {
                println!("{}", serde_json::to_string(&rows).unwrap_or_else(|_| "[]".into()));
            } else if rows.is_empty() {
                println!("(no projects)");
            } else {
                for r in &rows {
                    println!("{}\t{}", r["key"].as_str().unwrap_or(""), r["architect"].as_str().unwrap_or("(unassigned)"));
                }
            }
            Ok(())
        }
        "set" => {
            let key = args.positional.get(2).ok_or_else(|| format!("usage: {prog} architect set <key> <persona>"))?;
            let persona = args.positional.get(3).ok_or_else(|| format!("usage: {prog} architect set <key> <persona>"))?;
            check_architect_persona(persona)?;
            if !store::set_architect(&conn, key, persona, bsc_util::now_ms())? {
                return Err(format!("{prog} architect set: no such project '{key}' (list them with `{prog} list`)"));
            }
            print_architect_row(&conn, key, prog)
        }
        "clear" => {
            let key = args.positional.get(2).ok_or_else(|| format!("usage: {prog} architect clear <key>"))?;
            // A no-op clear (already unassigned) is NOT an error — the caller asked for a state, and
            // that state is what it gets. An absent KEY is different, and is caught by the read below.
            store::clear_architect(&conn, key, bsc_util::now_ms())?;
            print_architect_row(&conn, key, prog)
        }
        other => Err(format!("{prog} architect: unknown verb '{other}' (list | set | clear)")),
    }
}

/// Print the resulting `{ key, architect }` row, so a caller sees the STATE rather than inferring it
/// from an exit code. Errors when the key names no project.
fn print_architect_row(conn: &rusqlite::Connection, key: &str, prog: &str) -> Result<(), String> {
    let row = store::get(conn, key)
        .ok_or_else(|| format!("{prog} architect: no such project '{key}' (list them with `{prog} list`)"))?;
    println!("{}", serde_json::json!({ "key": row.key, "architect": row.architect }));
    Ok(())
}

/// Refuse a persona that is not an architect (#architects-own-projects).
///
/// WHY VALIDATE AT ALL, when `link add` happily takes free-text endpoints: a bad endpoint draws a
/// visibly wrong edge, whereas a bad architect id draws NOTHING — the project silently detaches from
/// every architect and reads as a rendering bug rather than a typo. The cheapest place to catch it is
/// the moment it is typed.
///
/// CANNOT-VERIFY IS NOT INVALID. The persona store is seeded by the desktop on first hydrate, so a
/// fresh install (or any environment where the app has never run) has an EMPTY store — refusing there
/// would make a correct assignment impossible on exactly the machines that need to bootstrap. An empty
/// or unreadable store therefore skips the check; a populated one enforces it.
fn check_architect_persona(persona: &str) -> Result<(), String> {
    let Some(base) = bsc_util::bsc_base_dir() else { return Ok(()) };
    let personas = bsc_json_store::Store::new(base.join("personas"), "persona").list();
    if personas.is_empty() {
        return Ok(()); // never seeded — cannot verify, so do not pretend to
    }
    let mut found_role: Option<String> = None;
    for raw in &personas {
        let Ok(v) = serde_json::from_str::<serde_json::Value>(raw) else { continue };
        if v.get("id").and_then(|i| i.as_str()) == Some(persona) {
            found_role = Some(v.get("role").and_then(|r| r.as_str()).unwrap_or("").to_string());
            break;
        }
    }
    match found_role.as_deref() {
        Some("architect") => Ok(()),
        Some(role) => Err(format!(
            "architect set: persona '{persona}' has role '{role}', not 'architect'.\n\
             Only an architect can own projects — list the candidates with `bsc persona list`."
        )),
        None => Err(format!(
            "architect set: no persona '{persona}' (list them with `bsc persona list`).\n\
             An assignment to a persona that does not exist would detach the project from every \
             architect in the graph, which reads as a rendering bug rather than a typo."
        )),
    }
}

/// `published get|set <key>` — read or set a project's in-place `.published` marker.
fn cmd_published(args: &Args, prog: &str) -> Result<(), String> {
    let sub = args.positional.get(1).map(String::as_str).unwrap_or("");
    match sub {
        "get" => {
            let key = args.positional.get(2).ok_or("usage: bsc project published get <key>")?;
            let pub_ = is_published(key);
            if args.json {
                println!("{pub_}");
            } else {
                println!("{}", if pub_ { "published" } else { "unpublished" });
            }
            Ok(())
        }
        "set" => {
            let key = args.positional.get(2).ok_or("usage: bsc project published set <key>")?;
            mark_published(key)?;
            if !args.json {
                println!("marked {key} published");
            }
            Ok(())
        }
        other => Err(format!(
            "unknown published command '{other}'\n\n{}",
            bsc_cli_util::help_for(prog, TAGLINE, COMMANDS, "published")
        )),
    }
}

/// `link list|add|set|remove` — the project-relationship edges (#2253). Defaults to `list`.
fn cmd_link(args: &Args, prog: &str) -> Result<(), String> {
    let sub = args.positional.get(1).map(String::as_str).unwrap_or("list");
    match sub {
        "list" => {
            // Output goes through the SHARED print helpers, not `println!`
            // (#the-warm-bsc-answers-the-boot-reads-too): this verb is answered by the warm `bsc serve`
            // child, which captures a request's output off the same stdout it speaks its protocol on.
            // A raw `println!` here would land in the protocol stream and corrupt every later response
            // on that child. Both helpers are byte-identical to `println!` when nothing is capturing,
            // which is what keeps the served and one-shot answers interchangeable.
            let links = load_links();
            if args.json {
                // Every row emits its target endpoint (#3786) so the desktop cache + agents see the full
                // contract; a legacy project link reads back as `{ "type": "project" }`.
                let arr: Vec<serde_json::Value> = links.iter().map(link_row_json).collect();
                bsc_sqlite_util::print_json(&arr, false);
            } else if links.is_empty() {
                bsc_cli_util::print_raw("(no project links)");
            } else {
                for l in &links {
                    // Human view: annotate a non-project target so the endpoint kind is visible at a glance.
                    let via = if l.target.kind == "project" { String::new() } else { format!(" [{}]", l.target.kind) };
                    bsc_cli_util::print_raw(&format!("{}\t{} -> {}{} ({})", l.id, l.from, l.to, via, l.kind));
                }
            }
            Ok(())
        }
        "add" => {
            let from = args.positional.get(2).ok_or("usage: bsc project link add <from> <to> <kind> [--target-type project|service|mcp] [--name …] [--url …] [--app-type …]")?;
            let to = args.positional.get(3).ok_or("usage: bsc project link add <from> <to> <kind>")?;
            let kind = args.positional.get(4).ok_or("usage: bsc project link add <from> <to> <kind>")?;
            // The target endpoint (#3786) — default is another project when no --target-type is given.
            // Empty descriptors are dropped rather than stored: `--name ""` means "no name", and
            // keeping it as `Some("")` would both write a meaningless `"name": ""` and — because
            // `is_nontrivial` only asks whether the field is SET — drag a `target` key onto a plain
            // project link that is supposed to serialize without one.
            let target = ContractTarget {
                kind: args.target_type.clone().unwrap_or_else(|| "project".into()),
                name: nonempty(&args.name),
                url: nonempty(&args.url),
                app_type: nonempty(&args.app_type),
            };
            let id = add_contract(from, to, kind, target)?;
            println!("{id}");
            Ok(())
        }
        // MODIFY (#architect-wires-project-relationships) — the verb `add` cannot be, because `add` is
        // idempotent by id and therefore discards the flags on a second call.
        "set" => {
            let id = args.positional.get(2).ok_or(
                "usage: bsc project link set <id> [--kind api|data|events] \
                 [--target-type project|service|mcp] [--name …] [--url …] [--app-type …]",
            )?;
            let patch = ContractPatch {
                kind: args.kind.clone(),
                target_type: args.target_type.clone(),
                name: args.name.clone(),
                url: args.url.clone(),
                app_type: args.app_type.clone(),
            };
            // A `set` with no flags would read the contract, write it back unchanged and report
            // success — indistinguishable from a real edit to any caller reading the exit code. Say
            // so instead, and name the flags, since a caller here has usually mistyped one.
            if [&patch.kind, &patch.target_type, &patch.name, &patch.url, &patch.app_type].iter().all(|f| f.is_none()) {
                return Err(format!(
                    "{prog} link set: nothing to change — pass at least one of --kind / --target-type / \
                     --name / --url / --app-type (an EMPTY value clears a descriptor)"
                ));
            }
            // Always JSON, regardless of --json (the `db` verbs' contract): a --kind change RE-KEYS the
            // link, so the caller's next command needs the id this prints.
            let link = update_contract(id, &patch)?;
            println!("{}", serde_json::to_string(&link_row_json(&link)).unwrap_or_else(|_| "null".into()));
            Ok(())
        }
        "remove" => {
            let id = args.positional.get(2).ok_or("usage: bsc project link remove <id>")?;
            remove_link(id)?;
            if !args.json {
                println!("removed {id}");
            }
            Ok(())
        }
        other => Err(format!(
            "unknown link command '{other}'\n\n{}",
            bsc_cli_util::help_for(prog, TAGLINE, COMMANDS, "link")
        )),
    }
}

/// `github-state [get]|set` — the persisted last-known GitHub board state (#2446). Defaults to
/// `get`; `set` reads the whole `{ records, fetchedAt }` envelope from stdin (validated by
/// `save_github_state`).
fn cmd_github_state(args: &Args, prog: &str) -> Result<(), String> {
    let sub = args.positional.get(1).map(String::as_str).unwrap_or("get");
    match sub {
        "get" => {
            match load_github_state() {
                // The state IS JSON — print it verbatim in both modes (`null` when absent under --json).
                Some(json) => println!("{json}"),
                None if args.json => println!("null"),
                None => println!("(no github state — no fetch has been mirrored yet)"),
            }
            Ok(())
        }
        "set" => {
            use std::io::Read;
            let mut buf = String::new();
            std::io::stdin().read_to_string(&mut buf).map_err(|e| format!("reading stdin: {e}"))?;
            save_github_state(&buf)?;
            if !args.json {
                println!("saved");
            }
            Ok(())
        }
        other => Err(format!(
            "unknown github-state command '{other}'\n\n{}",
            bsc_cli_util::help_for(prog, TAGLINE, COMMANDS, "github-state")
        )),
    }
}

/// `db add|get|list|remove|state` — the durable projects store (#2995). Timestamps (epoch millis)
/// are stamped HERE via `bsc_util::now_ms` so the store fns stay clock-free. Every verb prints
/// machine JSON on stdout (the frontend/agent contract), independent of the `--json` flag.
fn cmd_db(args: &Args, prog: &str) -> Result<(), String> {
    let sub = args.positional.get(1).map(String::as_str).unwrap_or("");
    match sub {
        "add" => {
            let input: AddInput = bsc_sqlite_util::read_stdin_json_one("project")?;
            let now = bsc_util::now_ms();
            let conn = store::open()?;
            // Get-then-upsert so a NEW key stamps createdAt=now while an existing key keeps its
            // original createdAt (the upsert SQL also preserves it — this belt-and-suspenders keeps
            // the printed row correct even on the insert branch).
            let prior = store::get(&conn, &input.key);
            let created_at = prior.as_ref().map(|r| r.created_at).unwrap_or(now);
            // #4088 — carry the existing triaged marker through. The upsert SQL already preserves it
            // on conflict; this keeps the INSERT branch and the printed row correct too.
            let triaged_at = prior.as_ref().and_then(|r| r.triaged_at);
            // …and the same for the architect assignment (#architects-own-projects). The stdin shape
            // carries no `architect` on purpose — ownership is set by `project architect set`, never by
            // a routine upsert — so without carrying the prior value the desktop's boot-time
            // draft-migration upsert would unassign every project it touched.
            let architect = prior.as_ref().and_then(|r| r.architect.clone());
            let row = ProjectRow {
                key: input.key,
                title: input.title,
                pitch: input.pitch,
                blueprint: input.blueprint,
                category: input.category,
                state: input.state.unwrap_or_else(|| "drafted".into()),
                created_at,
                updated_at: now,
                triaged_at,
                architect,
            };
            store::upsert(&conn, &row)?;
            let stored = store::get(&conn, &row.key).ok_or("db add: row vanished after upsert")?;
            bsc_sqlite_util::print_json(&stored, false);
            Ok(())
        }
        "get" => {
            let key = args.positional.get(2).ok_or("usage: bsc project db get <key>")?;
            let conn = store::open()?;
            // `Option<ProjectRow>` → the row object, or JSON `null` on a miss.
            bsc_sqlite_util::print_json(&store::get(&conn, key), false);
            Ok(())
        }
        "list" => {
            let conn = store::open()?;
            bsc_sqlite_util::print_json(&store::list(&conn), false);
            Ok(())
        }
        "remove" => {
            let key = args.positional.get(2).ok_or("usage: bsc project db remove <key>")?;
            let conn = store::open()?;
            let removed = store::remove(&conn, key)?;
            bsc_sqlite_util::print_json(&serde_json::json!({ "removed": removed }), false);
            Ok(())
        }
        "state" => {
            let key = args.positional.get(2).ok_or("usage: bsc project db state <key> <state>")?;
            let state = args.positional.get(3).ok_or("usage: bsc project db state <key> <state>")?;
            let conn = store::open()?;
            let row = store::set_state(&conn, key, state, bsc_util::now_ms())?
                .ok_or_else(|| format!("db state: no project '{key}'"))?;
            bsc_sqlite_util::print_json(&row, false);
            Ok(())
        }
        other => Err(format!(
            "unknown db command '{other}'\n\n{}",
            bsc_cli_util::help_for(prog, TAGLINE, COMMANDS, "db")
        )),
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn parse_args_collects_positionals_and_json_flag() {
        let a = parse_args(vec!["published".into(), "get".into(), "my-key".into(), "--json".into()]).unwrap();
        assert!(a.json);
        assert_eq!(a.positional, vec!["published", "get", "my-key"]);
    }

    #[test]
    fn parse_args_rejects_an_unknown_flag() {
        assert!(parse_args(vec!["list".into(), "--nope".into()]).is_err());
    }

    /// Write a throwaway plan.db carrying exactly `statuses`, one issue each.
    fn plan_db_with(dir: &std::path::Path, statuses: &[&str]) -> std::path::PathBuf {
        let db = dir.join("plan.db");
        let conn = bsc_sqlite_util::open_db(&db).unwrap();
        conn.execute("CREATE TABLE issues (ref TEXT, status TEXT)", []).unwrap();
        for (i, s) in statuses.iter().enumerate() {
            conn.execute("INSERT INTO issues (ref, status) VALUES (?1, ?2)", (format!("#{i}"), s))
                .unwrap();
        }
        db
    }

    #[test]
    fn count_issues_counts_done_as_complete_or_verified() {
        let dir = std::env::temp_dir().join(format!("bsc-progress-{}", std::process::id()));
        std::fs::create_dir_all(&dir).unwrap();
        let db = plan_db_with(&dir, &["open", "in_progress", "complete", "verified", "blocked", "failed"]);
        assert_eq!(count_issues(&db), Some((2, 6)));
        let _ = std::fs::remove_dir_all(&dir);
    }

    #[test]
    fn count_issues_treats_an_unknown_status_as_not_done() {
        // The denominator must still grow — a typo may not silently shrink the total and flatter the bar.
        let dir = std::env::temp_dir().join(format!("bsc-progress-unk-{}", std::process::id()));
        std::fs::create_dir_all(&dir).unwrap();
        let db = plan_db_with(&dir, &["complete", "kompleet"]);
        assert_eq!(count_issues(&db), Some((1, 2)));
        let _ = std::fs::remove_dir_all(&dir);
    }

    #[test]
    fn count_issues_is_none_without_a_db_or_an_issues_table() {
        let dir = std::env::temp_dir().join(format!("bsc-progress-none-{}", std::process::id()));
        std::fs::create_dir_all(&dir).unwrap();
        // Missing file ⇒ None (ABSENT, which the caller renders differently from "0 of 0").
        assert_eq!(count_issues(&dir.join("plan.db")), None);
        // Present but never planned ⇒ also None, not Some((0, 0)).
        let db = dir.join("plan.db");
        bsc_sqlite_util::open_db(&db).unwrap().execute("CREATE TABLE other (x INT)", []).unwrap();
        assert_eq!(count_issues(&db), None);
        let _ = std::fs::remove_dir_all(&dir);
    }

