    #[test]
    fn link_add_dispatch_persists_a_targeted_contract() {
        crate::testhome::with_home(|_home| {
            // A default (project) contract, an mcp-targeted one, and a service-targeted one via the CLI.
            run(vec!["link".into(), "add".into(), "app".into(), "billing".into(), "api".into()], "bsc project").unwrap();
            run(
                vec![
                    "link".into(), "add".into(), "app".into(), "postgres".into(), "data".into(),
                    "--target-type".into(), "mcp".into(), "--app-type".into(), "serverless".into(),
                ],
                "bsc project",
            )
            .unwrap();
            run(
                vec![
                    "link".into(), "add".into(), "app".into(), "stripe".into(), "api".into(),
                    "--target-type".into(), "service".into(), "--url".into(), "https://api.stripe.com".into(),
                ],
                "bsc project",
            )
            .unwrap();

            let links = crate::load_links();
            assert_eq!(links.len(), 3);
            assert_eq!(links.iter().find(|l| l.id == "app>billing:api").unwrap().target.kind, "project");
            let mcp = links.iter().find(|l| l.id == "app>postgres:data").unwrap();
            assert_eq!(mcp.target.kind, "mcp");
            assert_eq!(mcp.target.app_type.as_deref(), Some("serverless"));
            assert_eq!(links.iter().find(|l| l.id == "app>stripe:api").unwrap().target.url.as_deref(), Some("https://api.stripe.com"));

            // list dispatches (both modes) without error, and an unknown target type is rejected.
            run(vec!["link".into(), "list".into(), "--json".into()], "bsc project").unwrap();
            run(vec!["link".into(), "list".into()], "bsc project").unwrap();
            assert!(run(
                vec!["link".into(), "add".into(), "a".into(), "b".into(), "api".into(), "--target-type".into(), "widget".into()],
                "bsc project",
            )
            .is_err());
        });
    }

    /// #the-warm-bsc-answers-the-boot-reads-too — `project link list` is answered by the WARM `bsc
    /// serve` child, which captures a request's output off the same stdout it speaks its protocol on.
    /// This verb printed with raw `println!` on both branches, which would have written straight into
    /// that protocol stream and corrupted every later response on the child. The claim under test is
    /// therefore not "it prints the right thing" but "its output is CAPTURABLE" — an assertion that
    /// fails the moment someone reaches for `println!` here again.
    #[test]
    fn link_list_output_is_capturable_by_the_warm_serve_loop() {
        crate::testhome::with_home(|_home| {
            run(vec!["link".into(), "add".into(), "app".into(), "billing".into(), "api".into()], "bsc project").unwrap();

            let (r, captured) =
                bsc_util::capture_output(|| run(vec!["link".into(), "list".into(), "--json".into()], "bsc project"));
            r.unwrap();
            let rows: serde_json::Value = serde_json::from_str(captured.trim()).expect("captured JSON");
            assert_eq!(rows.as_array().unwrap().len(), 1, "the row reached the buffer, not stdout");
            assert_eq!(rows[0]["id"], "app>billing:api");

            // The human branch too — it shares the protocol stream just the same.
            let (r, captured) = bsc_util::capture_output(|| run(vec!["link".into(), "list".into()], "bsc project"));
            r.unwrap();
            assert!(captured.contains("app>billing:api"), "human view captured too: {captured:?}");

            // And the empty case, which is its own `print` call and its own chance to leak.
            run(vec!["link".into(), "remove".into(), "app>billing:api".into()], "bsc project").unwrap();
            let (r, captured) = bsc_util::capture_output(|| run(vec!["link".into(), "list".into()], "bsc project"));
            r.unwrap();
            assert!(captured.contains("no project links"), "{captured:?}");
        });
    }

    /// `link set` (#architect-wires-project-relationships) — the MODIFY verb, through the dispatcher.
    #[test]
    fn link_set_dispatch_patches_rekeys_and_refuses_a_no_op() {
        crate::testhome::with_home(|_home| {
            run(vec!["link".into(), "add".into(), "app".into(), "stripe".into(), "api".into(), "--target-type".into(), "service".into()], "bsc project").unwrap();

            // Patch the endpoint descriptor of a contract that already exists — the case a second
            // `add` silently discards.
            run(vec!["link".into(), "set".into(), "app>stripe:api".into(), "--url".into(), "https://api.stripe.com".into()], "bsc project").unwrap();
            assert_eq!(crate::load_links()[0].target.url.as_deref(), Some("https://api.stripe.com"));

            // `--kind` re-keys through the dispatcher too.
            run(vec!["link".into(), "set".into(), "app>stripe:api".into(), "--kind".into(), "data".into()], "bsc project").unwrap();
            assert_eq!(crate::load_links()[0].id, "app>stripe:data");

            // A flagless `set` would read-and-write-back unchanged and report success — say so instead.
            let err = run(vec!["link".into(), "set".into(), "app>stripe:data".into()], "bsc project").unwrap_err();
            assert!(err.contains("nothing to change"), "{err}");
            // As does a missing id, and an id that names no contract.
            assert!(run(vec!["link".into(), "set".into()], "bsc project").is_err());
            assert!(run(vec!["link".into(), "set".into(), "ghost>x:api".into(), "--url".into(), "u".into()], "bsc project").is_err());
            assert_eq!(crate::load_links().len(), 1, "no refusal wrote a row");
        });
    }

    /// An empty descriptor flag on `add` means ABSENT, not `""` — otherwise `is_nontrivial` would drag
    /// a `target` key onto a plain project link and break the #3786 byte-compat guarantee.
    #[test]
    fn link_add_treats_an_empty_descriptor_flag_as_absent() {
        crate::testhome::with_home(|_home| {
            run(vec!["link".into(), "add".into(), "app".into(), "billing".into(), "api".into(), "--name".into(), "   ".into()], "bsc project").unwrap();
